//classes
import { Thread } from "./Thread.js";
import { Threads } from "../Threads.js";
export class ThreadPool {
    name;
    _totalThreads = 0;
    _currentThread = 0;
    __threads = [];
    constructor(name) {
        this.name = name;
    }
    getThreads() {
        return this.__threads;
    }
    connectToThread(threadToConnectTo) {
        for (const thread of this.__threads) {
            thread.connectToThread(threadToConnectTo);
        }
    }
    destroyAll() {
        for (const thread of this.__threads) {
            thread.destroy();
        }
    }
    isReady() {
        let ready = true;
        for (const thread of this.__threads) {
            if (!thread.isPortSet)
                ready = false;
        }
        return ready;
    }
    waitTillAllAreReady() {
        return new Promise((resolve, reject) => {
            const inte = setInterval(() => {
                if (this.isReady()) {
                    clearInterval(inte);
                    resolve(true);
                }
            }, 1);
        });
    }
    addPort(port) {
        const threadName = `${this.name}-${this._totalThreads}`;
        const thread = new Thread(threadName, this._totalThreads, this.name, this);
        thread.index = this._totalThreads;
        Threads.addThread(thread);
        thread.setPort(port);
        this.__threads.push(thread);
        this._totalThreads++;
    }
    runTaskForAll(id, data, transfers) {
        for (let i = 0; i < this.__threads.length; i++) {
            this.__threads[i].runTask(id, data, transfers);
        }
    }
    nextThread() {
        return this.__threads[this.__handleCount()];
    }
    runTask(id, data, transfers, onDone, threadNumber, excludeThread) {
        if (typeof threadNumber !== "number") {
            if (this._currentThread == excludeThread) {
                this.__handleCount();
            }
            const thread = this.__threads[this._currentThread];
            thread.runTask(id, data, transfers, onDone);
            return this.__handleCount();
        }
        else {
            const thread = this.__threads[threadNumber];
            thread.runTask(id, data, transfers, onDone);
            return threadNumber;
        }
    }
    runTaskAsync(id, data, transfers, threadNumber, excludeThread) {
        return new Promise((resolve) => {
            this.runTask(id, data, transfers, resolve, threadNumber, excludeThread);
        });
    }
    __handleCount() {
        let countReturn = this._currentThread;
        this._currentThread++;
        if (this._currentThread >= this._totalThreads) {
            this._currentThread = 0;
        }
        return countReturn;
    }
}
